import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_conv3d_cuda = load_inline(
    name="conv3d_single_kernel_ext",
    cpp_sources=r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>

torch::Tensor conv3d_cuda_forward(
    const torch::Tensor& input,
    const torch::Tensor& weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &conv3d_cuda_forward, "Single-kernel CUDA Conv3d forward");
}
""",
    cuda_sources=r"""
#include <torch/extension.h>
#include <ATen/AccumulateType.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t, typename acc_t>
__global__ void conv3d_forward_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int64_t N,
    int64_t Cin,
    int64_t Din,
    int64_t Hin,
    int64_t Win,
    int64_t Cout,
    int64_t Dout,
    int64_t Hout,
    int64_t Wout,
    int64_t K,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups,
    bool has_bias) {
    const int64_t ow = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const int64_t oh = static_cast<int64_t>(blockIdx.y) * blockDim.y + threadIdx.y;
    const int64_t packed = static_cast<int64_t>(blockIdx.z);
    const int64_t od = packed % Dout;
    const int64_t tmp = packed / Dout;
    const int64_t oc = tmp % Cout;
    const int64_t n = tmp / Cout;

    if (n >= N || oc >= Cout || od >= Dout || oh >= Hout || ow >= Wout) {
        return;
    }

    const int64_t cin_per_group = Cin / groups;
    const int64_t cout_per_group = Cout / groups;
    const int64_t group = oc / cout_per_group;
    const int64_t cin_start = group * cin_per_group;

    acc_t sum = acc_t(0);

    for (int64_t ic_local = 0; ic_local < cin_per_group; ++ic_local) {
        const int64_t ic = cin_start + ic_local;

        for (int64_t kd = 0; kd < K; ++kd) {
            const int64_t id = od * stride - padding + kd * dilation;
            if (id < 0 || id >= Din) {
                continue;
            }

            for (int64_t kh = 0; kh < K; ++kh) {
                const int64_t ih = oh * stride - padding + kh * dilation;
                if (ih < 0 || ih >= Hin) {
                    continue;
                }

                for (int64_t kw = 0; kw < K; ++kw) {
                    const int64_t iw = ow * stride - padding + kw * dilation;
                    if (iw < 0 || iw >= Win) {
                        continue;
                    }

                    const int64_t input_idx =
                        (((n * Cin + ic) * Din + id) * Hin + ih) * Win + iw;

                    const int64_t weight_idx =
                        ((((oc * cin_per_group + ic_local) * K + kd) * K + kh) * K + kw);

                    sum += static_cast<acc_t>(input[input_idx]) *
                           static_cast<acc_t>(weight[weight_idx]);
                }
            }
        }
    }

    if (has_bias) {
        sum += static_cast<acc_t>(bias[oc]);
    }

    const int64_t output_idx =
        (((n * Cout + oc) * Dout + od) * Hout + oh) * Wout + ow;

    output[output_idx] = static_cast<scalar_t>(sum);
}

torch::Tensor conv3d_cuda_forward(
    const torch::Tensor& input,
    const torch::Tensor& weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.dim() == 5, "input must have shape [N, C, D, H, W]");
    TORCH_CHECK(weight.dim() == 5, "weight must have shape [Cout, Cin/groups, K, K, K]");
    TORCH_CHECK(stride > 0, "stride must be positive");
    TORCH_CHECK(dilation > 0, "dilation must be positive");
    TORCH_CHECK(groups > 0, "groups must be positive");
    TORCH_CHECK(input.scalar_type() == weight.scalar_type(),
                "input and weight must have the same dtype");

    const auto N = input.size(0);
    const auto Cin = input.size(1);
    const auto Din = input.size(2);
    const auto Hin = input.size(3);
    const auto Win = input.size(4);

    const auto Cout = weight.size(0);
    const auto cin_per_group = weight.size(1);
    const auto K = weight.size(2);

    TORCH_CHECK(weight.size(3) == K && weight.size(4) == K,
                "only cubic kernels are supported");
    TORCH_CHECK(Cin % groups == 0, "input channels must be divisible by groups");
    TORCH_CHECK(Cout % groups == 0, "output channels must be divisible by groups");
    TORCH_CHECK(cin_per_group == Cin / groups,
                "weight channel dimension does not match input/groups");

    if (bias.has_value() && bias->defined()) {
        TORCH_CHECK(bias->is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias->scalar_type() == input.scalar_type(),
                    "bias must have the same dtype as input");
        TORCH_CHECK(bias->numel() == Cout, "bias has incorrect size");
    }

    const auto effective_k = dilation * (K - 1) + 1;
    const auto Dout = (Din + 2 * padding - effective_k) / stride + 1;
    const auto Hout = (Hin + 2 * padding - effective_k) / stride + 1;
    const auto Wout = (Win + 2 * padding - effective_k) / stride + 1;

    TORCH_CHECK(Dout >= 0 && Hout >= 0 && Wout >= 0,
                "calculated output size is invalid");

    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();

    auto output = torch::empty(
        {N, Cout, Dout, Hout, Wout},
        input.options());


    c10::cuda::CUDAGuard device_guard(input.device());
    cudaStream_t stream = at::cuda::getCurrentCUDAStream(input.device().index());

    const dim3 block(8, 8, 1);
    const dim3 grid(
        static_cast<unsigned int>((Wout + block.x - 1) / block.x),
        static_cast<unsigned int>((Hout + block.y - 1) / block.y),
        static_cast<unsigned int>(N * Cout * Dout));

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        input.scalar_type(),
        "conv3d_forward_cuda",
        [&] {
            using acc_t = at::acc_type<scalar_t, true>;

            const scalar_t* bias_data = nullptr;
            bool has_bias = false;

            if (bias.has_value() && bias->defined()) {
                auto bias_c = bias->contiguous();
                bias_data = bias_c.data_ptr<scalar_t>();
                has_bias = true;

                conv3d_forward_kernel<scalar_t, acc_t><<<grid, block, 0, stream>>>(
                    input_c.data_ptr<scalar_t>(),
                    weight_c.data_ptr<scalar_t>(),
                    bias_data,
                    output.data_ptr<scalar_t>(),
                    N, Cin, Din, Hin, Win,
                    Cout, Dout, Hout, Wout,
                    K, stride, padding, dilation, groups,
                    has_bias);
            } else {
                conv3d_forward_kernel<scalar_t, acc_t><<<grid, block, 0, stream>>>(
                    input_c.data_ptr<scalar_t>(),
                    weight_c.data_ptr<scalar_t>(),
                    nullptr,
                    output.data_ptr<scalar_t>(),
                    N, Cin, Din, Hin, Win,
                    Cout, Dout, Hout, Wout,
                    K, stride, padding, dilation, groups,
                    false);
            }
        });

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
""",
    functions=None,
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv3d = nn.Conv3d(
            in_channels,
            out_channels,
            (kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _conv3d_cuda.forward(
            x,
            self.conv3d.weight,
            self.conv3d.bias,
            self.conv3d.stride[0],
            self.conv3d.padding[0],
            self.conv3d.dilation[0],
            self.conv3d.groups,
        )

